from lesson_helpers import *
import re
from bs4 import BeautifulSoup
pops=[]
def add(k,title,body,ids):pops.append('<template data-pop="'+k+'" data-title="'+html.escape(title,quote=True)+'">'+body+ref(*ids)+'</template>')
summary=[('Confirmer les hématies, distinguer le phénotype de sa cause et ne pas déduire un pronostic du mot bénin.','CH-HUG-DEF'),('Le dénominateur et la population changent la fréquence observée ; aucune incidence suisse N02 n’est extrapolée.','EU-ALPORT-RISK'),('Un signe commun peut traduire un défaut structural, une maladie immune ou une lésion des voies excrétrices.','EU-ALPORT-RISK'),('La gravité décide du délai ; la répétition sur plusieurs mois ne s’applique qu’au patient stable.','CH-HUG-ORIENT'),('Chronologie, famille et expositions donnent des hypothèses ; les examens apportent les preuves.','EU-ALPORT-GEN'),('L’examen cherche le retentissement ; une consultation rassurante n’annule pas une albuminurie.','CH-HUG-ORIENT'),('Les profils isolé, protéinurique et rapidement progressif n’imposent pas les mêmes examens.','INT-IGA-DX'),('IgA exige une biopsie ; un variant génétique exige une interprétation clinique et familiale.','EU-ALPORT-GEN'),('Chaque examen doit répondre à une question de localisation, de gravité ou de mécanisme.','EU-YOUNG'),('Séparer pigment, saignement urinaire, origine glomérulaire et cause étiologique.','CH-HUG-DEF'),('Traiter un risque démontré ; une hématurie seule ne justifie pas une immunosuppression.','EU-ALPORT-TX'),('Le suivi porte sur pression, protéines et trajectoire de fonction ; le sang seul ne résume pas le risque.','EU-ALPORT-SUIVI'),('Relier le signe au raisonnement clinique et distinguer exercice original et question fédérale officielle.','CH-PROFILES'),('Un indice n’est pas une preuve, une normalité initiale n’est pas une promesse, un plafond n’est pas une dose obligatoire.','CH-HUG-ORIENT')]
for part in ['a','b']:
 path=CH/('N02_'+part+'.html');txt=path.read_text()
 for i,(summary_text,sid) in enumerate(summary,1):
  pattern=r'(<section\b[^>]*id="n02-'+str(i)+r'"[^>]*>)(.*?)(</section>)'
  m=re.search(pattern,txt,re.S)
  if not m:continue
  title=BeautifulSoup(m[2],'html.parser').find(['h2','h3']).get_text(' ',strip=True)
  paras=re.findall(r'<p>(.*?)</p>',m[2],re.S)[:2]
  add('n02-exp-'+str(i),title,'<p>'+('</p><p>'.join(paras))+'</p>',(sid,))
  add('pareto-n02-'+str(i),'Raisonnement essentiel — '+title,'<p>'+summary_text+'</p><p>Reprendre les critères, méthodes et limites de la section avant une décision individuelle.</p>',(sid,))
  buttons='<p>'+w('exp-'+str(i),'Comprendre le raisonnement')+'</p><button class="pareto-btn ui" data-k="pareto-n02-'+str(i)+'">▲ Loi de Pareto — Le raisonnement essentiel</button>'
  txt=txt[:m.end(2)]+buttons+txt[m.end(2):]
 path.write_text(txt)
add('n02-calcul-acr','Calculer un rapport sans perdre l’analyte','''<p>Sur un même prélèvement fictif, l’albumine est à 60 mg/L et la créatinine à 1 g/L. Le rapport albumine/créatinine vaut 60 ÷ 1 = 60 mg/g ; les litres s’annulent. Ce résultat ne vaut ni 60 g/g ni 60 mg d’albumine par jour.</p><p>Si l’on mesure les protéines totales à 1,2 g/L et la créatinine à 1 g/L, le rapport protéines/créatinine vaut 1,2 g/g. Ce second analyte correspond aux seuils de certains traitements IgA ; le premier correspond notamment au suivi albuminurique du collagène IV. Les deux ne sont pas interchangeables.</p><p>Ces nombres illustrent le calcul, pas une indication isolée. Vérifier la persistance, la présence de sang visible, le contexte et les unités du laboratoire avant d’appliquer un seuil clinique.</p>''',('EU-YOUNG','EU-ALPORT-SUIVI','FI-FILSPARI','FI-KINPEYGO'))
add('n02-calcul-dose','Dose par surface : un exemple européen hors indication suisse','''<p>Exemple pédagogique fictif : une surface corporelle déjà mesurée à 0,8 m² et une dose de ramipril de 1 mg/m²/j donnent 1 × 0,8 = 0,8 mg/j. Le maximum européen de 6 mg/m²/j donnerait 4,8 mg/j pour cette même surface. Ce calcul explique les unités ; il ne choisit ni formulation, ni arrondi, ni dose pour un enfant réel.</p><p>ERKNet/ERA/ESPN propose un début à 1–2 mg/m²/j dans Alport. La FI suisse Ramipril Zentiva ne recommande pas le produit avant 18 ans. La prescription pédiatrique demeure spécialisée et hors indication, avec surveillance ; ne pas confondre mg/m², mg/kg et mg par personne.</p>''',('EU-ALPORT-TX','FI-RAMIPRIL'))
cases=[('La bandelette ne suffit pas','''<p>Une personne sans symptôme a une bandelette positive après une course intense. Sa créatinine est stable. Le premier objectif est de confirmer les érythrocytes et de contrôler dans des conditions adaptées, tout en recherchant une cause transitoire et les paramètres de risque. La bandelette ne démontre ni une IgA, ni une indication de scanner ou de corticoïde.</p><p>Si l’anomalie persiste, documenter sédiment, protéines, pression et fonction, puis choisir une orientation. Si une complication apparaît, le délai change immédiatement.</p>''',('CH-HUG-DEF','CH-HUG-ORIENT')),('Une famille, plusieurs risques','''<p>Une jeune femme et sa mère ont une hématurie persistante. L’audition paraît normale et l’albuminurie n’est pas encore connue. Reconstituer l’arbre familial, mesurer albuminurie et fonction, et discuter une analyse COL4A3/4/5. L’absence de surdité ne suffit pas à exclure une maladie du collagène IV.</p><p>Ne pas promettre une maladie bénigne et ne pas débuter un traitement sur le seul caractère familial. Génotype et albuminurie déterminent notamment le moment du blocage rénine–angiotensine.</p>''',('EU-ALPORT-GEN','EU-ALPORT-TX')),('Un chiffre change la question','''<p>Chez un adulte avec hématurie glomérulaire persistante et protéinurie de 0,7 g/j, une IgA fait partie des hypothèses. KDIGO propose de considérer une biopsie à partir de 0,5 g/j lorsque l’IgA est possible et le geste réalisable. Ce seuil n’établit pas l’IgA : la biopsie apporte la preuve.</p><p>Ce même chiffre ne correspond pas automatiquement aux indications suisses Filspari ou Kinpeygo, qui retiennent au moins 1 g/j ou leur rapport protéines/créatinine propre. Une concentration d’IgA sérique ne remplace pas le diagnostic rénal.</p>''',('INT-IGA-DX','FI-FILSPARI','FI-KINPEYGO')),('La trajectoire décide de l’urgence','''<p>Une personne suivie pour hématurie développe dyspnée et hausse rapide de créatinine. Il faut évaluer immédiatement le retentissement et organiser une prise en charge urgente, sans attendre plusieurs mois de prélèvements. Une histoire ancienne stable n’explique pas automatiquement la nouvelle détérioration.</p><p>Un génotype connu n’exclut pas une maladie surajoutée ; des croissants seuls ne définissent pas une IgA rapidement progressive. Le bilan réunit fonction, clinique et histologie selon le contexte.</p>''',('CH-HUG-ORIENT','EU-ALPORT-RISK','INT-IGA-SPECIAL'))]
for i,(title,body,ids) in enumerate(cases,1):add('n02-cas-'+str(i),'Cas '+str(i)+' — '+title,'<p><b>Exercice original fictif.</b></p>'+body,ids)
# Calculations are accessible from the normal/scientific and pharmacological contexts.
for part,anchor,keyid,label in [('c','s-bio-content','calcul-acr','Calculer et interpréter un rapport urinaire'),('d','p-ramipril','calcul-dose','Comprendre la dose en mg/m²')]:
 path=CH/('N02_'+part+'.html');txt=path.read_text();pat=r'(<section\b[^>]*id="n02-'+anchor+r'"[^>]*>.*?)(</section>)';txt=re.sub(pat,lambda m:m[1]+'<p>'+w(keyid,label)+'</p>'+m[2],txt,count=1,flags=re.S);path.write_text(txt)
quizzes=[('Bandelette sang positive : IgA certaine ?','Non : confirmer les hématies et leur origine.','Oui : la bandelette identifie les dépôts.','Le test détecte l’hème ; le diagnostic d’IgA exige une biopsie.','CH-HUG-DEF'),('Une surdité absente exclut-elle COL4A3/4/5 ?','Non : le phénotype varie selon gène, âge et sexe.','Oui : la triade est toujours complète.','L’histoire et les paramètres rénaux restent utiles même sans signe auditif.','EU-ALPORT-GEN'),('Filspari s’ajoute-t-il au losartan ?','Non : il remplace le blocage usuel.','Oui : le double blocage est toujours préférable.','La FI contre-indique l’association aux ARA ; KDIGO évite aussi l’association aux IEC.','FI-FILSPARI'),('60 mg/L d’albumine et 1 g/L de créatinine : quel rapport ?','60 mg/g.','60 g/j.','Diviser les concentrations du même prélèvement ; les litres s’annulent, pas les unités des analytes.','EU-ALPORT-SUIVI')]
path=CH/'N02_b.html';txt=path.read_text();pat=r'(<section\b[^>]*id="n02-13"[^>]*>.*?)(</section>)'
qhtml=''.join('<div class="quiz ui"><p>'+q+'</p><button data-ok="1">'+yes+'</button><button data-ok="0">'+no+'</button><p class="fb" hidden>'+ex+'</p></div>'+ref(sid) for q,yes,no,ex,sid in quizzes)
txt=re.sub(pat,lambda m:m[1]+qhtml+m[2],txt,count=1,flags=re.S);path.write_text(txt)
save('pop1','\n'.join(pops[:16]));save('pop2','\n'.join(pops[16:]));print(len(pops),'fenêtres,14Pareto,4quiz')
